// Match a received raw frame against FANB. Returns fan*8 + cmd, or -1.
// Skips the first pulse (receiver AGC clips it) and the trailing gap (idle
// timeout cuts it). Pulses are compared as short/long symbols, not durations:
// the SRX882 stretches marks by up to ~180us on strong signals (B2 remote
// gave 470-560us for 379us marks), which a % tolerance can't absorb.
inline int fanb_match(const std::vector<int32_t> &x, int32_t split = 565) {
  auto sym = [&](int32_t v) { return (v < 0 ? -1 : 1) * (std::abs(v) > split ? 2 : 1); };
  for (int f = 0; f < 3; f++)
    for (int c = 0; c < 5; c++) {
      const auto &t = FANB[f][c];
      size_t n = t.size() - 1;
      if (x.size() < n) continue;
      bool ok = true;
      for (size_t i = 1; i < n && ok; i++) ok = sym(x[i]) == sym(t[i]);
      if (ok) return f * 8 + c;
    }
  return -1;
}
